function App() {
  const [text, setText] = useState('');
  const [list, setList] = useState([]);
  const [isPending, startTransition] = useTransition();
  const onChange = (e) => {
    const value = e.target.value;
    setText(value); // urgent: keeps the input responsive
    startTransition(() => {
      // low-priority: building 8000 rows can be interrupted
      const rows = Array.from({ length: 8000 }, (_, i) => `${value} - row ${i}`);
      setList(rows);
    });
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={onChange} placeholder="Type fast..." />
      {isPending && <span style={{ marginLeft: 8, color: '#888' }}>updating…</span>}
      <ul style={{ maxHeight: 160, overflow: 'auto' }}>
        {list.slice(0, 50).map((r, i) => <li key={i}>{r}</li>)}
      </ul>
    </div>
  );
}

function App() {
