const auditLog = [];

function App() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    auditLog.push(count); // runs after commit, once per committed value
  }, [count]);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Count: {count}</h2>
      <p>Log length: {auditLog.length}</p>
      <button onClick={() => setCount(c => c + 1)}>+1</button>
    </div>
  );
}

function App() {
  const all = Array.from({ length: 6000 }, (_, i) => `Item ${i}`);
  const [query, setQuery] = useState('');
  const deferred = useDeferredValue(query);
  const isStale = deferred !== query;
  const results = all.filter(x => x.includes(deferred));
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Filter..." />
      <p>{results.length} matches</p>
      <ul style={{ opacity: isStale ? 0.5 : 1, maxHeight: 160, overflow: 'auto' }}>
        {results.slice(0, 50).map((r, i) => <li key={i}>{r}</li>)}
      </ul>
    </div>
  );
}
